do $$declare missing text;begin select string_agg(name,', ')into missing from(values('location_current_points'),('location_viewer_snapshots'),('location_access_logs'),('shared_meeting_points'),('context_arrival_statuses'))x(name)where not exists(select 1 from information_schema.tables where table_schema='public'and table_name=x.name);if missing is not null then raise exception 'Missing Stage 7 tables: %',missing;end if;if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='start_location_share_v1')then raise exception 'Start workflow missing';end if;if not exists(select 1 from pg_trigger where tgname='blocks_revoke_location_sharing'and not tgisinternal)then raise exception 'Blocking revocation missing';end if;if not exists(select 1 from pg_policies where schemaname='public'and tablename='location_viewer_snapshots'and policyname='viewers read sanitized current snapshots')then raise exception 'Viewer isolation missing';end if;if has_table_privilege('authenticated','public.location_current_points','INSERT')then raise exception 'Direct coordinate writes allowed';end if;if has_function_privilege('authenticated','public.expire_location_shares_v1(integer)','EXECUTE')then raise exception 'Expiry worker exposed to authenticated users';end if;if not has_function_privilege('service_role','public.expire_location_shares_v1(integer)','EXECUTE')then raise exception 'Expiry worker unavailable to service role';end if;end$$;
